import {transformDefaults,normalizeTransformSettings} from './transforms.js';
import {parseLength} from './dimensions.js';

export function initTransformUI(api){let settings;try{settings=normalizeTransformSettings(JSON.parse(api.getPref('transform-settings','{}')));}catch{settings=transformDefaults();}const $=s=>document.querySelector(s);api.studio()?.setTransformSettings(settings);
 function inspectorHTML(part){const s=settings,u=api.project().units,f=u==='in'?25.4:1;return `<div class="transform-settings"><div class="fields two"><label>Handle axes<select data-transform-setting="space"><option value="world"${s.space==='world'?' selected':''}>World X / Y / Z</option><option value="local"${s.space==='local'?' selected':''}>Part X / Y / Z</option></select></label><label class="check"><input type="checkbox" data-transform-setting="magnet"${s.magnet?' checked':''}> Snap nearby</label></div><details data-disclosure="transform-snap"><summary>Snap increments &amp; gap</summary><div class="fields">${[['step','Move step ('+u+')',s.step/f],['angle','Turn step (°)',s.angle],['gap','Contact gap ('+u+')',s.gap/f]].map(([key,label,value])=>`<label>${label}<input type="text" data-transform-setting="${key}" value="${+value.toFixed(4)}"></label>`).join('')}</div><p class="hint">Step 0 = free. Alt bypasses snapping while dragging. Nearby snaps align nominal centers, edges or touching faces; the target turns green. Use Snap to a face for exact face alignment.</p></details></div>`;}
 document.addEventListener('change',e=>{const key=e.target.dataset.transformSetting;if(!key)return;try{const v=key==='magnet'?e.target.checked:key==='space'?e.target.value:key==='angle'?Number(e.target.value):parseLength(e.target.value,api.project().units);if(key==='angle'&&!e.target.value.trim())throw Error('Enter a rotation step.');settings=normalizeTransformSettings({...settings,[key]:v});api.studio()?.setTransformSettings(settings);api.setPref('transform-settings',JSON.stringify(settings));api.notify('Transform snapping updated.');}catch(err){api.notify(err.message);api.refresh();}});
 function sync(tool,attached){if(!api.studio()?.transformDraft)$('#transformReadout').hidden=true;for(const b of document.querySelectorAll('[data-tool]')){b.classList.toggle('active',b.dataset.tool===tool);b.setAttribute('aria-pressed',b.dataset.tool===tool);}
  $('#viewHint').textContent=attached?(tool==='rotate'?'Drag X / Y / Z rings to rotate · G: move · Alt: free':'Drag X / Y / Z arrows or plane squares · R: rotate · Alt: free'):'Drag to orbit · scroll to zoom · right-drag to pan';
 }
 function preview(id,pos,rot,snaps=[],ended=false){const p=api.project().parts.find(p=>p.id===id);if(!p)return;const unit=api.project().units,f=unit==='in'?25.4:1;
  for(const [key,values] of [['pos',pos.map(n=>n/f)],['rot',rot]])for(let i=0;i<3;i++){const el=$(`[data-prop="${key}.${i}"]`);if(el&&document.activeElement!==el)el.value=+values[i].toFixed(4);}
  const readout=$('#transformReadout');readout.hidden=ended;if(!ended){const position=pos.map((n,i)=>'XYZ'[i]+' '+(n/f).toFixed(unit==='in'?3:2)).join(' · '),rotation=rot.map((n,i)=>'XYZ'[i]+' '+n.toFixed(1)+'°').join(' · ');readout.textContent=(api.studio()?.tool==='rotate'?rotation:position+' '+unit)+(snaps.length?' — '+snaps.map(s=>s.axis+' '+s.kind+' → '+s.name).join('; '):'');}
 }
 return {inspectorHTML,sync,preview,settings:()=>({...settings})};
}
